import React, { useState } from "react";
import "./styles.css";

export default function App() {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [age, setAge] = useState("");

  const handleRegister = (e) => {
    e.preventDefault();
    if (!name || !phone) {
      alert("Please enter your name and phone number!");
      return;
    }
    alert(`✅ Registered Successfully!\nName: ${name}\nPhone: ${phone}\nAge: ${age}`);
    setName("");
    setPhone("");
    setAge("");
  };

  return (
    <div>
      {/* Navbar */}
      <header className="navbar">
        <a href="/" className="brand">
          NextGen Health
        </a>
        <nav>
          <a href="/">Home</a>
          <a href="/dashboard">Dashboard</a>
          <a href="/contact">Contact</a>
        </nav>
      </header>

      {/* Hero Section */}
      <section className="hero">
        <h1>NextGen Health Smart Care</h1>
        <p>
          Manage appointments, connect with doctors, and access personalized care — all from one secure platform.
        </p>

        <div className="hero-buttons">
          <button className="btn">Get Started</button>
          <button className="btn">Learn More</button>
        </div>

        {/* Registration Card */}
        <div style={{ marginTop: "3rem" }}>
          <div className="card">
            <h3 style={{ marginBottom: "1rem" }}>Quick Patient Registration</h3>
            <form onSubmit={handleRegister}>
              <input
                type="text"
                placeholder="Full Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
              <input
                type="tel"
                placeholder="Mobile Number"
                value={phone}
                onChange={(e) => setPhone(e.target.value)}
              />
              <input
                type="number"
                placeholder="Age"
                value={age}
                onChange={(e) => setAge(e.target.value)}
              />
              <button type="submit">Register</button>
            </form>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="footer">
        © {new Date().getFullYear()} NextGen Health | Designed by Hardik Jindal
      </footer>
    </div>
  );
}
